<script setup lang="ts">
const { request, accessToken } = useAppApi();
const draft = ref(''); const posts = ref([{ id: '1', name: 'tran ngoc', time: '8 ngày', content: 'cho mình hỏi kinh nghiệm muốn nghe tốt thì phải học như thế nào?', tags: ['Listening'], comments: 12 }, { id: '2', name: 'Nguyễn Lê Bích Chi', time: '5 ngày', content: 'nghe đoạn ngắn tầm 2-3p, chép đến khi nào không chép nổi nữa rồi mới xem transcript nhé.', tags: ['Dictation'], comments: 8 }]); const notice = ref('');
async function createPost() { if (!draft.value.trim()) return; const content = draft.value.trim(); if (accessToken.value) { try { await request('/community/posts', { method: 'POST', body: { type: 'QUESTION', content, tags: ['Learner'] } }); } catch { notice.value = 'Bài đã được giữ ở bản nháp trên màn hình này.'; } } posts.value.unshift({ id: String(Date.now()), name: 'Bạn', time: 'vừa xong', content, tags: ['Learner'], comments: 0 }); draft.value = ''; }
</script>

